    if (count > 4) return Array.from({ length: count }, (_, i) => { const a = -0.75 * Math.PI + i * 2 * Math.PI / count; return { x: Math.cos(a) * D * sx * 1.25, y: Math.sin(a) * D * sy * 1.25 }; });
