  const noise = (i, j, s = 0) => { const v = Math.sin(i * 127.1 + j * 311.7 + s * 74.7) * 43758.5453; return v - Math.floor(v); };

  // the sprite sheet, decoded once into a blob URL (short enough to reference from every sprite)
