    if (sheetUrl) return sheetUrl;
    try { const bin = atob(ART_SHEET.slice(ART_SHEET.indexOf(',') + 1)), bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      sheetUrl = URL.createObjectURL(new Blob([bytes], { type: 'image/webp' })); } catch { sheetUrl = ART_SHEET; }
