    const band = x => !x.t ? 3 : now - x.t <= WEEK ? 0 : now - x.t <= 30 * DAY ? 1 : 2, newest = [...m.items].sort((x, y) => (y.t - x.t) || x.short.localeCompare(y.short));
    const of = n => newest.filter(x => band(x) === n), older = [...of(2), ...of(3)];
