      const r = { x0: sx - w / 2, x1: sx + w / 2, y0: sy, y1: sy + 16 }, hit = placed.some(p => r.x0 < p.x1 && r.x1 > p.x0 && r.y0 < p.y1 && r.y1 > p.y0);
