    const d = ks => ks.map(k => { const [i, j] = k.split(',').map(Number); return 'M' + [iso(i, j), iso(i + 1, j), iso(i + 1, j + 1), iso(i, j + 1)].map(pt).join('L') + 'Z'; }).join('');
    const [i0, j0, i1, j1] = p.r, edge = [iso(i0, j0), iso(i1, j0), iso(i1, j1), iso(i0, j1)].map(pt).join(' '), at = iso(i1, j1);
