    el.innerHTML = `<path class="lp-woods" d="${d([...one.woods.keys()])}"/><path class="lp-strip" d="${d([...one.strip.keys()])}"/>`
      + `<path class="lp-${p.type}" d="${d(keys.filter(k => !deep.has(k) && !causeway.has(k)))}"/><path class="lp-water" d="${d([...deep])}"/><path class="lp-strip" d="${d([...causeway.keys()])}"/>`
      + `<polygon class="lp-edge" points="${edge}"/><text class="lp-label" x="${f1(at.x)}" y="${f1(at.y)}" dy="1.3em" text-anchor="middle">${esc(word)}</text>`;
    el.classList.toggle('blocked', !ok);
